#include <stddef.h>
#include <string.h>

/* 取出 s 指向的那一层长度，并把 *next 指向下一层起点（或字符串结尾） */
static int mqtt_level_len(const char *s, const char **next)
{
    const char *p = s;
    while (*p != '\0' && *p != '/') {
        p++;
    }
    *next = (*p == '/') ? (p + 1) : p;
    return (int)(p - s);
}

int mqtt_topic_match(const char *filter, const char *topic)
{
    const char *f = filter;
    const char *t = topic;

    if (filter == NULL || topic == NULL || *filter == '\0' || *topic == '\0') {
        return -1;
    }

    for (;;) {
        const char *fn = NULL;
        const char *tn = NULL;
        int flen;
        int tlen;

        /* 过滤器剩余部分恰好是 #：匹配零个或多个剩余层级 */
        if (f[0] == '#' && f[1] == '\0') {
            return 1;
        }
        if (t[0] == '\0') {
            return 0;   /* 主题已耗尽，过滤器还有层级 */
        }

        flen = mqtt_level_len(f, &fn);
        tlen = mqtt_level_len(t, &tn);

        if (flen == 1 && f[0] == '+') {
            if (tlen == 0) {
                return 0;   /* + 要求该层非空 */
            }
        } else if (flen != tlen || memcmp(f, t, (size_t)flen) != 0) {
            return 0;       /* 逐层精确比较失败 */
        }

        if (fn[0] == '\0' && tn[0] == '\0') {
            return 1;       /* 两侧同时耗尽，层级数一致 */
        }
        if (fn[0] == '\0' || tn[0] == '\0') {
            /* 一侧还有层级：只有过滤器剩下的恰好是 # 才算匹配 */
            return (fn[0] == '#' && fn[1] == '\0') ? 1 : 0;
        }

        f = fn;
        t = tn;
    }
}
